'use client';

import React, { useState } from 'react';
import { UtensilsCrossed, Wind, DoorClosed, ChevronRight } from 'lucide-react';
import { listingData } from '../../constants/listing-data';

export function HostAndHighlights() {
  const { host, features, translationNotice, description } = listingData;
  const [isDescOpen, setIsDescOpen] = useState(false);

  const getFeatureIcon = (name: string) => {
    switch (name) {
      case 'UtensilsCrossed':
        return <UtensilsCrossed size={24} className="text-[#222222]" />;
      case 'Wind':
        return <Wind size={24} className="text-[#222222]" />;
      case 'DoorClosed':
        return <DoorClosed size={24} className="text-[#222222]" />;
      default:
        return <DoorClosed size={24} className="text-[#222222]" />;
    }
  };

  return (
    <div className="font-cereal">
      {/* Host Summary */}
      <div className="flex items-center gap-4 py-1">
        <div
          className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-[10px] text-white select-none ${host.avatarBg}`}
        >
          {host.avatarText}
        </div>
        <div className="flex flex-col">
          <h3 className="text-[16px] font-semibold text-[#222222] leading-snug">
            Hosted by {host.name}
          </h3>
          <p className="text-[14px] text-[#717171] leading-tight mt-0.5">
            Superhost · {host.hostingDuration}
          </p>
        </div>
      </div>

      <div className="w-full h-px bg-[#DDDDDD] my-6" />

      {/* Features highlights */}
      <div className="flex flex-col space-y-6 py-1">
        {features.map((f) => (
          <div key={f.id} className="flex items-start gap-6">
            <div className="mt-0.5 shrink-0">{getFeatureIcon(f.iconName)}</div>
            <div>
              <h4 className="text-[16px] font-medium text-[#222222] leading-snug">
                {f.title}
              </h4>
              <p className="text-[14px] text-[#717171] leading-normal mt-0.5">
                {f.description}
              </p>
            </div>
          </div>
        ))}
      </div>

      <div className="w-full h-px bg-[#DDDDDD] my-6" />

      {/* Translation Notice */}
      <div className="bg-[#F7F7F7] rounded-xl px-4 py-3.5 my-2 flex items-center gap-1.5 text-[14px] text-[#222222]">
        <span>{translationNotice.noticeText}</span>
        <button
          type="button"
          className="font-semibold underline hover:text-black cursor-pointer focus:outline-none"
        >
          {translationNotice.actionText}
        </button>
      </div>

      <div className="w-full h-px bg-[#DDDDDD] my-6" />

      {/* Description */}
      <div className="py-1 text-[#222222]">
        <p className="text-[16px] leading-[1.5] whitespace-pre-line">
          {description.previewTop}
        </p>
        <button
          type="button"
          onClick={() => setIsDescOpen(!isDescOpen)}
          className="mt-3 font-semibold underline text-[#222222] hover:text-black cursor-pointer inline-flex items-center gap-1 focus:outline-none"
        >
          {isDescOpen ? 'Show less' : 'Show more'}
          <ChevronRight size={18} />
        </button>

        {isDescOpen && (
          <div className="mt-4 pt-4 border-t border-[#EBEBEB] text-[15px] leading-relaxed text-[#222222] space-y-3">
            {description.paragraphs.map((p, idx) => (
              <p key={idx}>{p}</p>
            ))}
          </div>
        )}
      </div>

      <div className="w-full h-px bg-[#DDDDDD] my-6" />
    </div>
  );
}
