'use client';

import React, { useState, useEffect, useRef } from 'react';
import { Navbar } from '@/components/navigation/Navbar';
import { ListingHeader } from './components/header/ListingHeader';
import { PhotoGrid } from './components/gallery/PhotoGrid';
import { PropertySummary } from './components/property-summary/PropertySummary';
import { HostAndHighlights } from './components/property-summary/HostAndHighlights';
import { SleepSection } from './components/sleeping/SleepSection';
import { AmenitiesSection } from './components/amenities/AmenitiesSection';
import { CalendarSection } from './components/calendar/CalendarSection';
import { BookingCard } from './components/booking/BookingCard';
import { ReviewsSection } from './components/reviews/ReviewsSection';
import { LocationSection } from './components/location/LocationSection';
import { HostCard } from './components/host/HostCard';
import { ThingsToKnow } from './components/things-to-know/ThingsToKnow';
import { NearbyListings } from './components/nearby-listings/NearbyListings';
import { PhotoTour } from './components/photo-tour/PhotoTour';
import { ReviewsModal } from './components/lightbox/ReviewsModal';
import { Footer } from '@/components/footer/Footer';
import { listingData } from './constants/listing-data';

export function ListingClientShell() {
  const [isCompact, setIsCompact] = useState(false);
  const [activeSection, setActiveSection] = useState('photos');
  const [isPhotoTourOpen, setIsPhotoTourOpen] = useState(false);
  const [isReviewsModalOpen, setIsReviewsModalOpen] = useState(false);

  const photosRef = useRef<HTMLDivElement>(null);

  // Scroll observer for compact header
  useEffect(() => {
    const el = photosRef.current;
    if (!el) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        setIsCompact(!entry.isIntersecting);
      },
      {
        root: null,
        threshold: 0.1,
        rootMargin: '-60px 0px 0px 0px',
      }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // Section observer to track active section in compact navbar
  useEffect(() => {
    const sectionIds = ['photos', 'amenities', 'reviews', 'location'];
    const elements = sectionIds
      .map((id) => document.getElementById(id))
      .filter(Boolean) as HTMLElement[];

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setActiveSection(entry.target.id);
          }
        });
      },
      {
        root: null,
        rootMargin: '-20% 0px -70% 0px',
        threshold: 0,
      }
    );

    elements.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, []);

  const handleSectionClick = (id: string) => {
    const el = document.getElementById(id);
    if (el) {
      const top = el.getBoundingClientRect().top + window.pageYOffset - 90;
      window.scrollTo({ top, behavior: 'smooth' });
      setActiveSection(id);
    }
  };

  const handleReserveClick = () => {
    const el = document.getElementById('reservation-card-container');
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  };

  return (
    <div className="min-h-screen bg-white text-[#222222] font-cereal">
      {/* Top Header & Floating Compact Navbar */}
      <Navbar
        compact={isCompact}
        activeSection={activeSection}
        onSectionClick={handleSectionClick}
        pricing={{
          formattedTotalPrice: listingData.pricing.formattedTotalPrice,
          nights: listingData.pricing.nights,
        }}
        rating={listingData.guestFavorite.rating}
        reviewCount={listingData.guestFavorite.reviewCount}
        onReserve={handleReserveClick}
        onScrollToPhotos={() => handleSectionClick('photos')}
      />

      {/* Main Page Layout Container */}
      <main className="max-w-[1400px] mx-auto px-10 sm:px-20 lg:px-40 py-6">
        {/* Title, Share, Save */}
        <ListingHeader title={listingData.title} />

        {/* 5-Photo Hero Bento Grid */}
        <div id="photos" ref={photosRef} className="scroll-mt-28 mb-6">
          <PhotoGrid
            onShowAll={() => setIsPhotoTourOpen(true)}
            onPhotoClick={() => setIsPhotoTourOpen(true)}
          />
        </div>

        {/* Two-Column Grid: Left details + Right sticky booking card */}
        <div className="grid grid-cols-1 lg:grid-cols-[1fr_370px] gap-16 relative pt-4 pb-10">
          <div className="min-w-0 flex flex-col">
            <PropertySummary />
            <HostAndHighlights />
            <SleepSection />
            <AmenitiesSection onShowAll={() => {}} />
            <CalendarSection />
          </div>

          <div>
            <BookingCard onReserve={handleReserveClick} />
          </div>
        </div>

        <div className="w-full h-px bg-[#DDDDDD] my-6" />

        {/* Reviews Section with Laurel Center and 7-col breakdown */}
        <ReviewsSection onShowAll={() => setIsReviewsModalOpen(true)} />

        <div className="w-full h-px bg-[#DDDDDD] my-6" />

        {/* Location / Map */}
        <LocationSection />

        <div className="w-full h-px bg-[#DDDDDD] my-6" />

        {/* Meet Your Host */}
        <HostCard />

        <div className="w-full h-px bg-[#DDDDDD] my-6" />

        {/* Things to Know */}
        <ThingsToKnow />

        <div className="w-full h-px bg-[#DDDDDD] my-6" />

        {/* More Stays Nearby */}
        <NearbyListings />
      </main>

      {/* Footer */}
      <Footer />

      {/* Photo Tour Modal Overlay */}
      {isPhotoTourOpen && (
        <PhotoTour onClose={() => setIsPhotoTourOpen(false)} />
      )}

      {/* Reviews Full Modal Overlay */}
      <ReviewsModal
        isOpen={isReviewsModalOpen}
        onClose={() => setIsReviewsModalOpen(false)}
      />
    </div>
  );
}
