'use client';

import React, { useState, useEffect } from 'react';
import { X, Search } from 'lucide-react';
import { ReviewCard, ReviewItem } from '../reviews/ReviewCard';
import { reviewsData } from '../../constants/listing-data';

interface ReviewsModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export function ReviewsModal({ isOpen, onClose }: ReviewsModalProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [activeTag, setActiveTag] = useState<string | null>(null);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpen]);

  if (!isOpen) return null;

  const { overallRating = 4.95, reviewCount = 19, keywordTags = [], items = [] } = reviewsData;

  const filteredItems = (items as unknown as ReviewItem[]).filter((r) => {
    const matchesSearch =
      searchTerm.trim() === '' ||
      r.content.toLowerCase().includes(searchTerm.toLowerCase()) ||
      r.author.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesTag = !activeTag || (r.tags && r.tags.includes(activeTag));

    return matchesSearch && matchesTag;
  });

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-10 bg-black/50 backdrop-blur-xs font-cereal">
      <div className="bg-white w-full max-w-[880px] max-h-[90vh] rounded-2xl flex flex-col shadow-2xl overflow-hidden">
        {/* Header */}
        <div className="sticky top-0 bg-white border-b border-[#EBEBEB] px-6 py-4 flex items-center justify-between z-10">
          <button
            type="button"
            onClick={onClose}
            className="w-8 h-8 rounded-full flex items-center justify-center hover:bg-gray-100 transition cursor-pointer"
          >
            <X size={20} className="text-[#222222]" />
          </button>
          <h3 className="text-[18px] font-semibold text-[#222222]">
            ★ {Number(overallRating).toFixed(2)} · {reviewCount} reviews
          </h3>
          <div className="w-8" />
        </div>

        {/* Modal Scroll Body */}
        <div className="overflow-y-auto px-8 py-6 space-y-6">
          {/* Search bar */}
          <div className="relative">
            <Search
              size={18}
              className="absolute left-4 top-1/2 -translate-y-1/2 text-[#717171]"
            />
            <input
              type="text"
              placeholder="Search all reviews..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-11 pr-4 py-3 bg-[#F7F7F7] border border-[#DDDDDD] rounded-xl text-[15px] text-[#222222] placeholder-[#717171] focus:outline-none focus:border-black transition-colors"
            />
          </div>

          {/* Keyword tags */}
          <div className="flex flex-wrap gap-2">
            {keywordTags.map((tag) => {
              const isSelected = activeTag === tag.id;
              return (
                <button
                  key={tag.id}
                  type="button"
                  onClick={() => setActiveTag(isSelected ? null : tag.id)}
                  className={`px-3.5 py-1.5 rounded-full text-[13px] font-medium border transition-colors cursor-pointer ${
                    isSelected
                      ? 'bg-[#222222] text-white border-[#222222]'
                      : 'bg-white text-[#222222] border-[#DDDDDD] hover:border-black'
                  }`}
                >
                  {tag.emoji} {tag.label} ({tag.count})
                </button>
              );
            })}
          </div>

          {/* Reviews list */}
          <div className="divide-y divide-[#EBEBEB] pt-4">
            {filteredItems.length > 0 ? (
              filteredItems.map((review) => (
                <div key={review.id} className="py-6 first:pt-0 last:pb-0">
                  <ReviewCard review={review} />
                </div>
              ))
            ) : (
              <div className="py-12 text-center text-[#717171]">
                <p className="text-[16px] font-medium text-[#222222]">
                  No reviews found for "{searchTerm}"
                </p>
                <p className="text-[14px] mt-1">
                  Try searching with another keyword or clearing the search bar.
                </p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
