'use client';

import React, { useState, useEffect } from 'react';
import { ArrowLeft, Share, Heart, X, ChevronLeft, ChevronRight } from 'lucide-react';
import { photoCategories } from '../../constants/listing-data';

interface PhotoTourProps {
  isOpen?: boolean;
  onClose: () => void;
  startIndex?: number;
}

export function PhotoTour({ isOpen = true, onClose }: PhotoTourProps) {
  const [activeCategory, setActiveCategory] = useState(photoCategories[0].id);
  const [selectedPhoto, setSelectedPhoto] = useState<string | null>(null);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpen]);

  if (!isOpen) return null;

  const scrollToCategory = (id: string) => {
    setActiveCategory(id);
    const el = document.getElementById(`tour-cat-${id}`);
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-white overflow-y-auto font-cereal text-[#222222]">
      {/* Sticky Header */}
      <header className="sticky top-0 bg-white/95 backdrop-blur-xs border-b border-[#EBEBEB] z-20 px-6 sm:px-10 h-16 sm:h-20 flex items-center justify-between">
        <button
          type="button"
          onClick={onClose}
          aria-label="Back"
          className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-gray-100 transition cursor-pointer"
        >
          <ArrowLeft size={20} className="text-[#222222]" />
        </button>

        <h1 className="text-[16px] font-semibold text-[#222222]">Photo tour</h1>

        <div className="flex items-center gap-2">
          <button
            type="button"
            aria-label="Share"
            className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-gray-100 transition cursor-pointer"
          >
            <Share size={18} className="text-[#222222]" />
          </button>
          <button
            type="button"
            aria-label="Save"
            className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-gray-100 transition cursor-pointer"
          >
            <Heart size={18} className="text-[#222222]" />
          </button>
        </div>
      </header>

      {/* Main Tour Content */}
      <main className="max-w-[1120px] mx-auto px-6 sm:px-12 py-8">
        {/* Category Pills Bar */}
        <div className="sticky top-20 bg-white py-4 mb-8 border-b border-[#EBEBEB] overflow-x-auto no-scrollbar flex items-center gap-2 z-10">
          {photoCategories.map((cat) => (
            <button
              key={cat.id}
              type="button"
              onClick={() => scrollToCategory(cat.id)}
              className={`px-4 py-2 rounded-full text-[14px] font-medium transition cursor-pointer shrink-0 ${
                activeCategory === cat.id
                  ? 'bg-[#222222] text-white'
                  : 'bg-[#F7F7F7] text-[#222222] hover:bg-gray-200'
              }`}
            >
              {cat.title}
            </button>
          ))}
        </div>

        {/* Categories Sections */}
        <div className="space-y-16 pb-20">
          {photoCategories.map((cat) => (
            <section key={cat.id} id={`tour-cat-${cat.id}`} className="scroll-mt-36">
              <h2 className="text-[24px] font-semibold text-[#222222] mb-3">
                {cat.title}
              </h2>
              {cat.amenities && cat.amenities.length > 0 && (
                <p className="text-[14px] text-[#717171] mb-6">
                  {cat.amenities.join(' · ')}
                </p>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {cat.images.map((imgSrc, imgIdx) => (
                  <div
                    key={imgIdx}
                    className="relative aspect-[4/3] rounded-xl overflow-hidden cursor-pointer group bg-gray-100"
                    onClick={() => setSelectedPhoto(imgSrc)}
                  >
                    <img
                      src={imgSrc}
                      alt={`${cat.title} photo ${imgIdx + 1}`}
                      className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                    />
                  </div>
                ))}
              </div>
            </section>
          ))}
        </div>
      </main>

      {/* Single Photo Lightbox Overlay */}
      {selectedPhoto && (
        <div className="fixed inset-0 z-60 bg-black flex items-center justify-center p-4">
          <button
            type="button"
            onClick={() => setSelectedPhoto(null)}
            className="absolute top-6 left-6 text-white hover:opacity-80 transition cursor-pointer"
          >
            <X size={28} />
          </button>
          <img
            src={selectedPhoto}
            alt="Expanded preview"
            className="max-w-full max-h-[90vh] object-contain rounded-lg"
          />
        </div>
      )}
    </div>
  );
}
