'use client';

import React, { useRef, useState } from 'react';
import { ChevronLeft, ChevronRight, Heart } from 'lucide-react';
import { nearbyStaysData } from '../../constants/listing-data';

export function NearbyListings() {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const totalPages = 2;

  const handleScroll = (dir: 'left' | 'right') => {
    if (!scrollRef.current) return;
    const offset = dir === 'left' ? -600 : 600;
    scrollRef.current.scrollBy({ left: offset, behavior: 'smooth' });
    if (dir === 'left') {
      setCurrentPage(Math.max(1, currentPage - 1));
    } else {
      setCurrentPage(Math.min(totalPages, currentPage + 1));
    }
  };

  return (
    <section id="nearby-stays" className="w-full py-8 font-cereal select-none">
      {/* Header with Carousel Controls */}
      <div className="flex items-center justify-between mb-6">
        <h2 className="text-[22px] font-medium text-[#222222]">
          More stays nearby
        </h2>
        <div className="flex items-center gap-3">
          <span className="text-[14px] text-[#717171]">
            {currentPage} / {totalPages}
          </span>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => handleScroll('left')}
              aria-label="Previous stays"
              className="w-8 h-8 rounded-full border border-[#DDDDDD] flex items-center justify-center hover:border-black transition cursor-pointer"
            >
              <ChevronLeft size={16} />
            </button>
            <button
              type="button"
              onClick={() => handleScroll('right')}
              aria-label="Next stays"
              className="w-8 h-8 rounded-full border border-[#DDDDDD] flex items-center justify-center hover:border-black transition cursor-pointer"
            >
              <ChevronRight size={16} />
            </button>
          </div>
        </div>
      </div>

      {/* Carousel Track */}
      <div
        ref={scrollRef}
        className="flex gap-4 overflow-x-auto no-scrollbar scroll-smooth pb-4"
      >
        {nearbyStaysData.map((stay) => (
          <div
            key={stay.id}
            className="min-w-[270px] max-w-[270px] flex flex-col group cursor-pointer"
          >
            <div className="relative aspect-square rounded-xl overflow-hidden bg-gray-100 mb-2">
              <img
                src={stay.image}
                alt={stay.title}
                className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
              />
              <button
                type="button"
                aria-label="Save to wishlist"
                className="absolute top-3 right-3 p-1.5 rounded-full hover:scale-110 active:scale-95 transition"
              >
                <Heart size={20} className="text-white drop-shadow-md stroke-[2]" />
              </button>
            </div>

            <div className="flex items-start justify-between gap-2">
              <h3 className="text-[15px] font-medium text-[#222222] truncate flex-1">
                {stay.title}
              </h3>
              <div className="flex items-center gap-1 text-[14px] text-[#222222] shrink-0">
                <span>★</span>
                <span>{stay.rating}</span>
              </div>
            </div>

            <p className="text-[14px] text-[#717171]">Candolim, India</p>

            <div className="flex items-baseline gap-1 mt-1">
              <span className="text-[15px] font-semibold text-[#222222]">
                {stay.price}
              </span>
              <span className="text-[14px] text-[#717171]">night</span>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}
